package gateway
import("context";"crypto/subtle";"encoding/json";"errors";"io";"net";"net/http";"strings";"github.com/madkoding/kitties/internal/orchestrator")
type driveManagementFleet interface{
 LexOpenDriveStatus(string)(orchestrator.DriveStatus,error)
 LexOpenDriveRead(context.Context,string,orchestrator.DriveRead)(orchestrator.DriveReadResult,error)
 LexOpenDriveCommand(context.Context,string,orchestrator.DriveCommand)(orchestrator.DriveCommandResult,error)
 LexOpenDriveCommandStatus(string,string)(orchestrator.DriveCommandResult,error)
 LexOpenDriveReconcile(context.Context,string,string,orchestrator.DriveReconcile)(orchestrator.DriveCommandResult,error)
}
func driveManagementError(w http.ResponseWriter,e error){status,code:=503,"drive_unavailable";var typed *orchestrator.DriveError;if errors.As(e,&typed){status,code=typed.Status,typed.Code};reply(w,status,map[string]any{"ok":false,"code":code,"error":"No se pudo confirmar la operación de Drive. No se repetirá automáticamente."})}
func(s *Server)driveManagementAllowed(w http.ResponseWriter,r *http.Request)(driveManagementFleet,bool){w.Header().Set("Cache-Control","no-store");address,_,e:=net.SplitHostPort(r.RemoteAddr);ip:=net.ParseIP(address);provided,bearer:=strings.CutPrefix(r.Header.Get("Authorization"),"Bearer ");if e!=nil||ip==nil||!ip.IsLoopback()||!bearer||s.token==""||subtle.ConstantTimeCompare([]byte(provided),[]byte(s.token))!=1{driveManagementError(w,&orchestrator.DriveError{Status:403,Code:"drive_forbidden"});return nil,false};f,ok:=s.fleet.(driveManagementFleet);if !ok{driveManagementError(w,&orchestrator.DriveError{Status:503,Code:"drive_unavailable"});return nil,false};return f,true}
func driveManagementDecode(w http.ResponseWriter,r *http.Request,value any,max int64)bool{d:=json.NewDecoder(http.MaxBytesReader(w,r.Body,max));d.DisallowUnknownFields();if d.Decode(value)!=nil||d.Decode(new(any))!=io.EOF{driveManagementError(w,&orchestrator.DriveError{Status:400,Code:"drive_request_invalid"});return false};return true}
func(s *Server)handleDriveManagementStatus(w http.ResponseWriter,r *http.Request){f,ok:=s.driveManagementAllowed(w,r);if !ok{return};out,e:=f.LexOpenDriveStatus(r.PathValue("alias"));if e!=nil{driveManagementError(w,e);return};reply(w,200,out)}
func(s *Server)handleDriveManagementRead(w http.ResponseWriter,r *http.Request){f,ok:=s.driveManagementAllowed(w,r);if !ok{return};var body orchestrator.DriveRead;if !driveManagementDecode(w,r,&body,8192){return};out,e:=f.LexOpenDriveRead(r.Context(),r.PathValue("alias"),body);if e!=nil{driveManagementError(w,e);return};reply(w,200,out)}
func(s *Server)handleDriveManagementCommand(w http.ResponseWriter,r *http.Request){f,ok:=s.driveManagementAllowed(w,r);if !ok{return};var body orchestrator.DriveCommand;if !driveManagementDecode(w,r,&body,6<<20){return};out,e:=f.LexOpenDriveCommand(r.Context(),r.PathValue("alias"),body);if e!=nil{driveManagementError(w,e);return};reply(w,200,out)}
func(s *Server)handleDriveManagementCommandStatus(w http.ResponseWriter,r *http.Request){f,ok:=s.driveManagementAllowed(w,r);if !ok{return};out,e:=f.LexOpenDriveCommandStatus(r.PathValue("alias"),r.PathValue("request"));if e!=nil{driveManagementError(w,e);return};reply(w,200,out)}
func(s *Server)handleDriveManagementReconcile(w http.ResponseWriter,r *http.Request){f,ok:=s.driveManagementAllowed(w,r);if !ok{return};var body orchestrator.DriveReconcile;if !driveManagementDecode(w,r,&body,4096){return};out,e:=f.LexOpenDriveReconcile(r.Context(),r.PathValue("alias"),r.PathValue("request"),body);if e!=nil{driveManagementError(w,e);return};reply(w,200,out)}
